// Valida a assinatura X-Hub-Signature-256 da Meta antes de olhar o conteúdo.
// Sem isso qualquer um posta atribuição falsa no CRM.
const crypto = require('crypto');
const segredo = $env.META_APP_SECRET;
const assinatura = $input.first().json.headers?.['x-hub-signature-256'] ?? '';
const corpo = JSON.stringify($input.first().json.body ?? {});
const esperado = 'sha256=' + crypto.createHmac('sha256', segredo).update(corpo).digest('hex');
const ok = assinatura.length === esperado.length &&
           crypto.timingSafeEqual(Buffer.from(assinatura), Buffer.from(esperado));
if (!ok) throw new Error('Assinatura da Meta inválida — evento descartado');
return $input.all();

// Fica só com a 1ª mensagem que carrega `referral` (o clique no anúncio).
// Mensagem normal, status de entrega e evento repetido saem aqui — a Kommo continua
// recebendo tudo por conta dela; este fluxo é só leitura paralela.
const saida = [];
for (const item of $input.all()) {
  for (const entry of (item.json.body?.entry ?? [])) {
    for (const ch of (entry.changes ?? [])) {
      const v = ch.value ?? {};
      for (const msg of (v.messages ?? [])) {
        const ref = msg.referral;
        if (!ref) continue;                       // mensagem sem origem de anúncio
        if (ref.source_type && ref.source_type !== 'ad') continue;
        const tel = String(msg.from || '').replace(/\D/g, '');
        if (!tel) continue;                       // dado incompleto
        saida.push({ json: {
          telefone: tel,
          messageId: msg.id,                      // chave de deduplicação
          quando: Number(msg.timestamp || 0),
          ctwaClid: ref.ctwa_clid ?? null,
          anuncioId: ref.source_id ?? null,
          titulo: ref.headline ?? null,
          corpo: ref.body ?? null,
          sourceUrl: ref.source_url ?? null,
          phoneNumberId: v.metadata?.phone_number_id ?? null,
        }});
      }
    }
  }
}
return saida;

// Deduplicação por message_id: a Meta reenvia o mesmo evento quando não recebe 2xx
// a tempo, e vários apps inscritos no WABA amplificam isso.
const vistos = $getWorkflowStaticData('global');
vistos.ids = vistos.ids || {};
const agora = Date.now();
for (const k of Object.keys(vistos.ids)) {          // janela de 24h
  if (agora - vistos.ids[k] > 86400000) delete vistos.ids[k];
}
const novos = [];
for (const item of $input.all()) {
  const id = item.json.messageId;
  if (vistos.ids[id]) continue;
  vistos.ids[id] = agora;
  novos.push(item);
}
return novos;

// Primeiro toque vence: só grava campo que está VAZIO no lead.
// Reatribuir um lead que já veio de outra campanha destrói o histórico de origem.
const F = { ad: 498572, titulo: 498574, clid: 498576, url: 498578, campanha: 397126, conjunto: 397128, primeiro: 397114 };
const rastreio = $('Deduplicar por message_id').item.json;
const leads = $input.first().json?._embedded?.leads ?? [];
if (!leads.length) return [{ json: { semLead: true, telefone: rastreio.telefone } }];

const lead = leads[0];
const atual = (id) => (lead.custom_fields_values ?? [])
  .find((c) => c.field_id === id)?.values?.[0]?.value ?? null;

const valores = [];
const por = (id, valor) => {
  if (valor === null || valor === undefined || valor === '') return;
  if (atual(id)) return;                       // já atribuído — não sobrescreve
  valores.push({ field_id: id, values: [{ value: String(valor) }] });
};
por(F.ad, rastreio.anuncioId);
por(F.titulo, rastreio.titulo);
por(F.clid, rastreio.ctwaClid);
por(F.url, rastreio.sourceUrl);
por(F.campanha, rastreio.anuncioId);           // sem nome da campanha no referral: fica o id
if (!atual(F.primeiro) && rastreio.quando) {
  valores.push({ field_id: F.primeiro, values: [{ value: rastreio.quando }] });
}
if (!valores.length) return [{ json: { semMudanca: true, leadId: lead.id } }];
return [{ json: { leadId: lead.id, telefone: rastreio.telefone, valores } }];
